import type { CallerHandoff } from './handoff';


export type RunnerVendor = 'claude' | 'codex' | 'cursor';

export const RUNNER_VENDOR_BINARIES: Record<RunnerVendor, string> = {
  claude: 'claude',
  codex: 'codex',
  cursor: 'cursor-agent',
};

export const EXECUTABLE_RUNNER_VENDORS: readonly RunnerVendor[] = [
  'claude',
  'codex',
  'cursor',
];

export const EXPLICIT_RUNNER_SELECTIONS: readonly string[] = [
  ...EXECUTABLE_RUNNER_VENDORS,
];

export const explicitRunnerSelectionError = (
  value: string | undefined,
): string | null => {
  if (value === undefined) {
    return null;
  }
  if (EXPLICIT_RUNNER_SELECTIONS.includes(value.trim().toLowerCase())) {
    return null;
  }
  return `Flag --agent must be one of ${EXPLICIT_RUNNER_SELECTIONS.join('|')} (got "${value}")`;
};

export type RunnerSource = 'flag' | 'user_config' | 'handoff' | 'declared';

export type ResolvedRunner =
  | {
      mode: 'runner';
      vendor: RunnerVendor;
      source: RunnerSource;
      binaryPath?: string;
    }
  | {
      mode: 'unavailable';
      reason: string;
    };

const asExecutableVendor = (value: string | undefined): RunnerVendor | null => {
  if (!value) return null;
  const candidate = value.trim().toLowerCase();
  return (EXECUTABLE_RUNNER_VENDORS as readonly string[]).includes(candidate)
    ? (candidate as RunnerVendor)
    : null;
};

const asExplicitSelection = (
  value: string | undefined,
): RunnerVendor | null => {
  return asExecutableVendor(value);
};

export type ResolveRunnerOptions = {
  explicitAgent?: string;
  configuredRunner?: string;
  handoff?: CallerHandoff | null;
  runnerPaths?: Partial<Record<RunnerVendor, string>>;
};

export const RUNNER_UNAVAILABLE_REMEDIATION =
  'If the CLI is installed as a shell alias (e.g. Claude Code\'s local ' +
  'install), expose a real binary (`ln -s ~/.claude/local/claude ' +
  '~/.local/bin/claude`) or set `runnerPaths.<vendor>` to its absolute ' +
  'path in ~/.rivet/config.json, then restart the session.';

export const resolveRunner = (
  options: ResolveRunnerOptions,
): ResolvedRunner => {
  const paths = options.runnerPaths ?? {};
  const runner = (
    vendor: RunnerVendor,
    source: RunnerSource,
  ): ResolvedRunner => ({
    mode: 'runner',
    vendor,
    source,
    ...(paths[vendor] ? { binaryPath: paths[vendor] } : {}),
  });

  const explicit = asExplicitSelection(options.explicitAgent);
  if (explicit) {
    return runner(explicit, 'flag');
  }

  const configured = asExplicitSelection(options.configuredRunner);
  if (configured) {
    return runner(configured, 'user_config');
  }

  const handoffVendor = asExecutableVendor(options.handoff?.agent);
  if (handoffVendor && paths[handoffVendor]) {
    return runner(handoffVendor, 'handoff');
  }

  for (const vendor of EXECUTABLE_RUNNER_VENDORS) {
    if (paths[vendor]) {
      return runner(vendor, 'declared');
    }
  }

  const missing = handoffVendor
    ? `no \`${RUNNER_VENDOR_BINARIES[handoffVendor]}\` binary (or any other vendor CLI)`
    : 'no vendor CLI (claude, codex, or cursor-agent)';
  return {
    mode: 'unavailable',
    reason:
      `${missing} was found in the invoking environment, and none is ` +
      `configured. ${RUNNER_UNAVAILABLE_REMEDIATION}`,
  };
};
